  const clamp = (z, lo, hi) => Math.min(hi, Math.max(lo, z));
  // Mountain car dynamics (same as adm/problems/mountain_car.py).
  const step = ([x, v], a) => {
    const v2 = clamp(v + 0.001 * a - 0.0025 * Math.cos(3 * x), -0.07, 0.07);
    return [clamp(x + v2, -1.2, 0.6), v2];
  };
  // Bilinear interpolation on the n x n grid: vals[i * n + j] is x index i, v index j.
  const U = ([x, v]) => {
    const zx = (x + 1.2) / 1.8 * (n - 1), zv = (v + 0.07) / 0.14 * (n - 1);
    const i = clamp(Math.floor(zx), 0, n - 2), j = clamp(Math.floor(zv), 0, n - 2);
    const fx = clamp(zx - i, 0, 1), fv = clamp(zv - j, 0, 1);
    return (1 - fx) * (1 - fv) * vals[i * n + j] + (1 - fx) * fv * vals[i * n + j + 1]
         + fx * (1 - fv) * vals[(i + 1) * n + j] + fx * fv * vals[(i + 1) * n + j + 1];
  };
  // Greedy policy: one-step lookahead, -1 per step, value 0 once the goal is reached.
  const act = s => [-1, 0, 1].map(a => { const s2 = step(s, a); return {a, q: -1 + (s2[0] >= 0.6 ? 0 : U(s2))}; })
                             .reduce((best, c) => c.q > best.q ? c : best).a;
  const path = [[x0, v0]];
  while (path[path.length - 1][0] < 0.6 && path.length <= 500) path.push(step(path[path.length - 1], act(path[path.length - 1])));
  const cells = [];
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++)
    cells.push({x: -1.2 + 1.8 * i / (n - 1), v: -0.07 + 0.14 * j / (n - 1), steps: -vals[i * n + j]});
  return {path, cells, reached: path[path.length - 1][0] >= 0.6};
}
